+    assert_eq!(
+        receipt.wait().await,
+        Err(CoreError::Application("cancelled".into()))
+    );
+    assert!(inbox.try_recv().is_err());
+    drop(inbox);
+    assert!(matches!(
+        app.request_user_shell(session, "next".into(), UserShellSelection::Existing(None)),
+        Err(CoreError::Shutdown)
+    ));
+}
